export const isGridItem = (element) => {
    const elProps = element.props;
    return elProps.gridLg !== undefined
        || elProps.gridMd !== undefined
        || elProps.gridSm !== undefined
        || elProps.gridLgStart !== undefined
        || elProps.gridMdStart !== undefined
        || elProps.gridSmStart !== undefined
        || elProps.gridStart !== undefined
        || elProps.grid !== undefined;
};
